mapper.update:
update reservation
userId = #{userid,jdbcType=INTEGER}, bookId = #{bookid,jdbcType=INTEGER}, status = #{status,jdbcType=TINYINT}, queuePosition = #{queueposition,jdbcType=INTEGER}, reserveTime = #{reservetime,jdbcType=TIMESTAMP}, expiryTime = #{expirytime,jdbcType=TIMESTAMP}, createTime = #{createtime,jdbcType=TIMESTAMP},
where reservationId = #{reservationid,jdbcType=INTEGER}

mapper.select:
select
from reservation where bookId = #{bookid} and status in (0, 1)
and userId = #{userid}
limit 1
